"use client";
import { useEffect, useState } from "react";
import { FiActivity, FiCheckCircle, FiClock, FiDownload, FiEye, FiFileText, FiPhoneCall, FiUsers, FiX } from "react-icons/fi";

type Call={id:string;call_type:string;status:string;lead_name?:string;lead_number?:string;duration_seconds?:number;outcome?:string;created_at:string;recording_url?:string;summary?:string;transcript?:string;agent_name:string;agent_avatar?:string};
const fmt=(s:number|undefined)=>{const n=Number(s||0);return `${Math.floor(n/60).toString().padStart(2,"0")}:${(n%60).toString().padStart(2,"0")}`};
const tone=(v:string)=>v.toLowerCase().replace(/\s+/g,"-").replace(/_/g,"-");
export default function BpoHistory(){const [calls,setCalls]=useState<Call[]>([]),[metrics,setMetrics]=useState<Record<string,number>>({}),[loading,setLoading]=useState(true),[preview,setPreview]=useState<Call|null>(null);
 useEffect(()=>{fetch("/api/bpo/calls").then(r=>r.json()).then(x=>{setCalls(x.calls||[]);setMetrics(x.metrics||{})}).catch(()=>{}).finally(()=>setLoading(false))},[]);
 const cards=[["Total calls",metrics.total||0,FiActivity,"purple"],["Calls today",metrics.today||0,FiClock,"blue"],["Completed",metrics.completed||0,FiCheckCircle,"green"],["Recordings",metrics.recordings||0,FiPhoneCall,"orange"]] as const;
 return <main className="bpo-history-page"><div className="bpo-heading"><div><p className="bpo-eyebrow">CALL OPERATIONS · HISTORY</p><h1>Call history</h1><p>Review BPO agent and manual dialing activity in one place.</p></div><span className="bpo-history-overview"><FiActivity /> Call overview</span></div>
 {loading?<><div className="bpo-history-kpis">{cards.map(([,,Icon,c])=><div className="bpo-skeleton-card" key={c}><i className="bpo-skeleton"/><span><b className="bpo-skeleton"/><em className="bpo-skeleton"/></span></div>)}</div><div className="bpo-history-table"><i className="bpo-skeleton skeleton-section"/>{[1,2,3,4,5].map(i=><i className="bpo-skeleton skeleton-row" key={i}/>)}</div></>:<><div className="bpo-history-kpis">{cards.map(([label,value,Icon,c])=><article key={label} className={c}><span><Icon/></span><div><small>{label}</small><strong>{value}</strong></div></article>)}</div><section className="bpo-history-table"><div className="bpo-history-table-head"><div><h2>Dialing activity</h2><p>Latest agent and manual dialing records</p></div><span>{calls.length} records</span></div><div className="bpo-table-scroll" role="region" aria-label="Call history" tabIndex={0}><table><thead><tr><th>Agent Info</th><th>Call duration</th><th>Outcome</th><th>Task status</th><th>Summary status</th><th>Action</th></tr></thead><tbody>{calls.map(c=><tr key={c.id}><td><div className="bpo-agent-cell">{c.agent_avatar?<img src={c.agent_avatar} alt=""/>:<span>{(c.agent_name||"?").slice(0,2).toUpperCase()}</span>}<div><strong>{c.agent_name}</strong><small>{c.lead_name||"Unknown lead"} · {c.call_type==="QUICK_DIAL"?"Manual dialing":"BPO agent"}</small></div></div></td><td>{fmt(c.duration_seconds)}</td><td><em className={`bpo-pill ${tone(c.outcome||"pending")}`}>{c.outcome||"Pending"}</em></td><td><em className={`bpo-pill ${c.status==="COMPLETED"?"completed":"progress"}`}>{c.status==="COMPLETED"?"Completed":"In progress"}</em></td><td><em className={`bpo-pill ${c.summary?"completed":"pending"}`}>{c.summary?"Ready":"Pending"}</em></td><td><div className="bpo-row-actions"><button onClick={()=>setPreview(c)} aria-label="View transcript" data-tooltip="View transcript"><FiEye/></button>{c.recording_url?<a href={c.recording_url} download target="_blank" rel="noreferrer" aria-label="Download recording" data-tooltip="Download recording"><FiDownload/></a>:<button disabled data-tooltip="No recording"><FiDownload/></button>}</div></td></tr>)}</tbody></table>{!calls.length&&<div className="bpo-history-empty"><div><FiClock /></div><h3>Your conversations, all in one place</h3><p>Once your team starts calling, review durations, outcomes and summaries here.</p><span>Agent calls and manual dialing activity will appear automatically.</span></div>}</div></section></>}
 {preview&&<div className="bpo-preview-overlay" onClick={()=>setPreview(null)}><section className="bpo-preview-modal" role="dialog" aria-modal="true" aria-label="Call transcript" onClick={e=>e.stopPropagation()}><button aria-label="Close transcript" onClick={()=>setPreview(null)}><FiX/></button><h2>Call transcript</h2><p>{preview.lead_name||"Unknown lead"} · {preview.agent_name}</p><pre>{preview.transcript||preview.summary||"Transcript is not available for this call yet."}</pre></section></div>}</main>}
