"use client";
import { useState } from "react";
import { FiDownload, FiEye, FiFileText, FiHardDrive, FiTrash2, FiX } from "react-icons/fi";
export default function BpoFileActions({id,name,type,content,kind,onDeleted}:{id:string;name:string;type?:string;content:string;kind:"script"|"leads";onDeleted?:()=>void}){const [preview,setPreview]=useState(false),[confirm,setConfirm]=useState(false),[busy,setBusy]=useState(false);const icon=type?.toLowerCase().includes("xls")?<FiHardDrive/>:<FiFileText/>;async function remove(){setBusy(true);const r=await fetch(`/api/bpo/scripts?id=${encodeURIComponent(id)}`,{method:"DELETE"});setBusy(false);if(r.ok){setConfirm(false);onDeleted?.();}}return <><article className="bpo-file-card"><span className={`bpo-file-icon ${kind}`}>
{icon}</span><div><strong>{name}</strong><small><em>{type||"FILE"}</em> · {kind==="leads"?`${content.split("\n").length} customer rows`:`${content.length.toLocaleString()} characters`}</small></div><div className="bpo-file-actions"><button onClick={()=>setPreview(true)} aria-label="Preview"><FiEye/></button><a href={`data:text/plain;charset=utf-8,${encodeURIComponent(content)}`} download={name} aria-label="Download"><FiDownload/></a><button className="delete" onClick={()=>setConfirm(true)} aria-label="Delete"><FiTrash2/></button></div></article>{preview&&<div className="bpo-preview-overlay"><div className="bpo-preview-modal"><button onClick={()=>setPreview(false)}><FiX/></button><h2>{name}</h2><p>{type||"FILE"} · Preview</p><pre>{content.slice(0,5000)}</pre></div></div>}{confirm&&<div className="bpo-preview-overlay"><div className="bpo-delete-modal"><FiTrash2/><h2>Delete this file?</h2><p>{name} and its paired workspace data will be removed.</p><div><button onClick={()=>setConfirm(false)}>Cancel</button><button className="delete" disabled={busy} onClick={remove}>{busy?"Deleting...":"Delete"}</button></div></div></div>}</>}
